package org.eclipse.rdf4j.sail.memory;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.function.Consumer;

import org.eclipse.rdf4j.query.QueryLanguage;
import org.eclipse.rdf4j.query.QueryParseOptions;
import org.eclipse.rdf4j.query.QueryParseOptions.GraphAlgebraMode;
import org.eclipse.rdf4j.query.parser.ParsedQuery;
import org.eclipse.rdf4j.query.parser.ParsedUpdate;
import org.eclipse.rdf4j.query.parser.QueryParser;
import org.eclipse.rdf4j.query.parser.QueryParserFactory;
import org.eclipse.rdf4j.query.parser.QueryParserRegistry;
import org.eclipse.rdf4j.query.parser.sparql.SPARQLParser;
import org.eclipse.rdf4j.query.parser.sparql.SPARQLParserFactory;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.repository.sail.SailRepositoryConnection;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.parallel.ResourceLock;

@ResourceLock("QueryParserRegistry")
class ParserFactoryGraphAlgebraCompatibilityTest {

	private static final QueryLanguage LANGUAGE = new QueryLanguage("LEGACY-GRAPH-COMPATIBILITY-TEST");
	private static final String QUERY = "SELECT ?g WHERE { GRAPH ?g {} }";

	@Test
	void builtInEvaluatorDoesNotForceGraphOnAnUnknownQueryParser() {
		withLegacyParser(connection -> {
			var query = connection.prepareTupleQuery(LANGUAGE, QUERY, null);
			assertEquals(GraphAlgebraMode.LEGACY, query.getParsedQuery().getParseOptions().graphAlgebraMode());
			assertEquals(GraphAlgebraMode.AUTO, connection.getQueryParseOptions().graphAlgebraMode());
			try (var rows = query.evaluate()) {
				assertTrue(rows.hasNext());
				assertFalse(rows.next().hasBinding("g"));
				assertFalse(rows.hasNext());
			}
		});
	}

	@Test
	void updatePreparationAlsoPreservesAnUnknownParser() {
		withLegacyParser(connection -> {
			connection.prepareUpdate(LANGUAGE,
					"INSERT { <urn:result> <urn:p> <urn:o> } WHERE { GRAPH <urn:missing> {} }", null).execute();
			assertEquals(1, connection.size());
		});
	}

	@Test
	void explicitLegacyStillUsesTheOldParserOverload() {
		withLegacyParser(connection -> {
			connection.setQueryParseOptions(QueryParseOptions.DEFAULT.withGraphAlgebraMode(GraphAlgebraMode.LEGACY));
			var query = connection.prepareTupleQuery(LANGUAGE, QUERY, null);
			assertEquals(GraphAlgebraMode.LEGACY, query.getParsedQuery().getParseOptions().graphAlgebraMode());
		});
	}

	@Test
	void explicitGraphIsNotSilentlyDowngradedForAnOldParser() {
		withLegacyParser(connection -> {
			connection.setQueryParseOptions(QueryParseOptions.DEFAULT.withGraphAlgebraMode(GraphAlgebraMode.GRAPH));
			assertThrows(UnsupportedOperationException.class,
					() -> connection.prepareTupleQuery(LANGUAGE, QUERY, null));
		});
	}

	@Test
	void anAuditedCustomParserFactoryCanOptIn() {
		QueryParserFactory factory = new SPARQLParserFactory() {
			@Override
			public QueryLanguage getQueryLanguage() {
				return LANGUAGE;
			}

			@Override
			public boolean supportsGraphAlgebra() {
				return true;
			}
		};
		withParserFactory(factory, connection -> {
			var query = connection.prepareTupleQuery(LANGUAGE, QUERY, null);
			assertEquals(GraphAlgebraMode.GRAPH, query.getParsedQuery().getParseOptions().graphAlgebraMode());
			try (var rows = query.evaluate()) {
				assertFalse(rows.hasNext(), "there are no named graphs to enumerate");
			}
		});
	}

	@Test
	void aFactorySubclassDoesNotInheritAnImplicitOptIn() {
		QueryParserFactory factory = new SPARQLParserFactory() {
			@Override
			public QueryLanguage getQueryLanguage() {
				return LANGUAGE;
			}
		};
		withParserFactory(factory, connection -> {
			var query = connection.prepareTupleQuery(LANGUAGE, QUERY, null);
			assertEquals(GraphAlgebraMode.LEGACY, query.getParsedQuery().getParseOptions().graphAlgebraMode());
		});
	}

	private static void withLegacyParser(Consumer<SailRepositoryConnection> action) {
		QueryParserFactory factory = new QueryParserFactory() {
			@Override
			public QueryLanguage getQueryLanguage() {
				return LANGUAGE;
			}

			@Override
			public QueryParser getParser() {
				return new QueryParser() {
					private final SPARQLParser parser = new SPARQLParser();

					@Override
					public ParsedQuery parseQuery(String query, String baseURI) {
						return parser.parseQuery(query, baseURI);
					}

					@Override
					public ParsedUpdate parseUpdate(String update, String baseURI) {
						return parser.parseUpdate(update, baseURI);
					}
				};
			}
		};
		withParserFactory(factory, action);
	}

	private static void withParserFactory(QueryParserFactory factory, Consumer<SailRepositoryConnection> action) {
		QueryParserRegistry registry = QueryParserRegistry.getInstance();
		var previous = registry.add(factory);
		SailRepository repository = new SailRepository(new MemoryStore());
		try (var connection = repository.getConnection()) {
			action.accept(connection);
		} finally {
			try {
				repository.shutDown();
			} finally {
				registry.remove(factory);
				previous.ifPresent(registry::add);
			}
		}
	}
}
